files.src/legacy.js:
export function legacyCalc(a, b) {
    return a + b;
}

files.src/use-a.js:
import { legacyCalc } from "./legacy.js";

export function sumPair(x, y) {
    return legacyCalc(x, y);
}

files.src/use-b.js:
import { legacyCalc } from "./legacy.js";

export function double(x) {
    return legacyCalc(x, x);
}

files.src/use-c.js:
import { legacyCalc } from "./legacy.js";

export function outerProduct(a, b) {
    return [legacyCalc(a, b), a * b];
}
